import React from 'react';
import {Icon} from "../icon/Icon";
import {animateScroll} from "react-scroll";


export const Logo = () => {
    const handleClick = () => {
        animateScroll.scrollToTop(); 
    };

    return (
        <a onClick={handleClick}>
            <Icon iconId={"codeSvg"} />
        </a>
    );
};

