import React from 'react';
import{S} from './Frooter_Styles'
import {Icon} from "../../components/icon/Icon";
import {FlexWrapper} from "../../components/FlexWrapper";



export const Footer:React.FC = () => {
    const DataSocialList=[
        {
            iconId:"instagram"
        },
        {
            iconId:"telegram"
        },
        {
            iconId:"vk"
        },
        {
            iconId:"linedin"
        },
    ]

    return (
        <S.StyledFooter >
            <FlexWrapper direction={"column"} align={"center"}>
            <S.Name>Illia</S.Name>
            <S.SocialIconList>
                {DataSocialList.map((el)=>
                    <S.SocialItem>
                        <S.SocioalIconLink>
                            <Icon height={'21px'} width={'21px'} viewBox={"0 0 21px 21px"} iconId={el.iconId} key={el.iconId}/>
                        </S.SocioalIconLink>
                    </S.SocialItem>
                )}
            </S.SocialIconList>
            <S.Copyright>© 2023 Illia Sobolevsky, All Rights Reserved.</S.Copyright>
            </FlexWrapper>

        </S.StyledFooter>
    );
};

