import React, {useState} from 'react';
import {S} from './work/Works_Styles'
import {SectionTitle} from "../../../components/SectionTitle";
import {TabMenu} from "./tabMenu/TabMenu";
import {FlexWrapper} from "../../../components/FlexWrapper";
import {Work} from "./work/Work";
import socialImg from './../../../assets/images/proj-1.pgn.webp'
import timerImg from './../../../assets/images/proj-2.webp'
import {Container} from "../../../components/Container";

export type tabsStatusType='all' | 'landing' | 'react' | 'spa'

export type tabObjType = {
    title: string,
    status: tabsStatusType
}

export type tabsItemsType = Array<tabObjType>;

const tabsItems: tabsItemsType = [
    {
        title: "All",
        status: "all",
    },
    {
        title: "Landing page",
        status: "landing",
    },
    {
        title: "React",
        status: "react"
    },
    {
        title: "Spa",
        status: "spa"
    },
]

const worksData = [
    {
        title: "Social Network",
        src: socialImg,
        text: "Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua Ut enim. Lorem ipsum dolor sit amet, consectetur adipisicing elit.",
        type: 'spa'
    },
    {
        title: "Timer",
        src: timerImg,
        text: "Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua Ut enim. Lorem ipsum dolor sit amet, consectetur adipisicing elit.",
        type: 'react'
    },
]

export const Works: React.FC = () => {
    const [currentFilterStatus, setCurrentFilterStatus] = useState('all')
    let filteredWorks = worksData

    if (currentFilterStatus === 'landing') {
        filteredWorks = worksData.filter(el => el.type === "landing")
    }
    if (currentFilterStatus === 'react') {
        filteredWorks = worksData.filter(el => el.type === "react")
    }
    if (currentFilterStatus === 'spa') {
        filteredWorks = worksData.filter(el => el.type === "spa")
    }

    const changeFilterStatus =(value:tabsStatusType)=>{
        setCurrentFilterStatus(value)
    }

    return (
        <S.StyledWorks id={'works'}>
            <Container>
                <SectionTitle>My Works</SectionTitle>
                <TabMenu currentFilterStatus={currentFilterStatus} tabsItems={tabsItems} changeFilterStatus={changeFilterStatus}/>
                <FlexWrapper justify={"space-between"} align={"flex-start"} wrap={'wrap'}>
                    {filteredWorks.map((work) => (
                        <Work
                            title={work.title}
                            text={work.text}
                            src={work.src}/>
                    ))}
                </FlexWrapper>
            </Container>

        </S.StyledWorks>
    );
};

